import {Spinner, Stack} from '@primer/react'
import {Blankslate} from '@primer/react/experimental'
import {AlertIcon} from '@primer/octicons-react'
import {clsx} from 'clsx'
import styles from './SummarySection.module.css'

interface SummarySectionProps {
  isError?: boolean
  isLoading?: boolean
  // we expect 1-3 summaries
  summaries:
    | [React.ReactNode]
    | [React.ReactNode, React.ReactNode]
    | [React.ReactNode, React.ReactNode, React.ReactNode]
}

export function SummarySection({isLoading, isError, summaries}: SummarySectionProps) {
  let content

  if (isLoading) {
    content = (
      <div className="Box d-flex flex-justify-center p-5">
        <Spinner size="large" />
      </div>
    )
  } else if (isError) {
    content = (
      <Blankslate border>
        <Blankslate.Visual>
          <AlertIcon size="medium" className="fgColor-muted" />
        </Blankslate.Visual>
        <Blankslate.Heading>License usage and payment summaries cannot be loaded</Blankslate.Heading>
        <Blankslate.Description>
          The license usage and payment summaries are currently unavailable due to a system error. Try reloading the
          page, or if the problem persists,{' '}
          <a href="https://support.github.com/contact" style={{textDecoration: 'underline'}}>
            contact support
          </a>
          .
        </Blankslate.Description>
      </Blankslate>
    )
  } else {
    content = (
      <Stack direction="horizontal" gap="spacious" className="pb-0" align="stretch">
        {summaries.map(summary => {
          const key = (summary as React.ReactElement)?.key ?? undefined
          return (
            <div key={key} className={clsx('Box', styles.box, 'p-3', styles.border)}>
              {summary}
            </div>
          )
        })}
      </Stack>
    )
  }

  return <div className="mb-3">{content}</div>
}

try{ SummarySection.displayName ||= 'SummarySection' } catch {}